def label_agent_trace(trace_log):
    histogram = {'specification': 0, 'misalignment': 0, 'verification': 0}
    for step in trace_log:
        if step.get('error') == 'schema_mismatch':
            histogram['verification'] += 1
        elif step.get('error') == 'unclear_role':
            histogram['specification'] += 1
        elif step.get('error') == 'context_lost':
            histogram['misalignment'] += 1
    return histogram

